<script setup>
import { ref, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import PaymentSuccessModal from '@/components/PromptComponent/PaymentSuccessModal.vue';
import { ElMessage } from 'element-plus';
import { getOrderDetail } from '@/api/order.js';
import { createPayment, mockConfirmPayment, queryPayment, waitForPayment } from '@/api/payment.js';
import { getRailwayOrderDetail } from '@/api/railway.js';
import { getMyMemberOrders } from '@/api/member.js';

const route = useRoute();
const router = useRouter();
const { t } = useI18n();

// 接收props参数
const props = defineProps({
  orderId: {
    type: String,
    default: ''
  },
  orderIds: {
    type: Array,
    default: () => []
  },
  cartItems: {
    type: Array,
    default: () => []
  },
  userId: {
    type: String,
    default: ''
  },
  /** 订单类型：mall（商城订单）/ railway（铁路车票订单）/ member（会员订单） */
  orderType: {
    type: String,
    default: 'mall'
  }
});

// 商品信息
const item = ref({});
// 订单ID
const orderId = ref('');

// 自定义提示框的状态
const isAlertVisible = ref(false);
const alertMessage = ref('');

// 选中的支付方式
const selectedPaymentMethod = ref('');

// 控制支付成功提示框的显示状态
const isPaymentModalVisible = ref(false);

// 订单时间
const orderTime = ref('');

// 支付处理状态
const paying = ref(false);
// 本次结算涉及的订单ID（购物车/预订可能一次支付多笔订单）
const orderIds = ref([]);
// 商城/预订订单详情
const orderDetails = ref([]);
// 铁路订单详情
const railwayOrder = ref(null);
// 会员订单详情
const memberOrder = ref(null);

// 生成当前时间作为订单时间
const generateOrderTime = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
};

// 加载铁路车票订单详情
const loadRailwayOrder = async () => {
  try {
    const response = await getRailwayOrderDetail(orderId.value);
    const order = response.data || {};
    railwayOrder.value = order;
    const yuan = Number(order.totalAmount || 0) / 100;
    item.value = {
      id: order.id,
      name: `${order.trainNo || ''} ${order.fromStationName || ''} → ${order.toStationName || ''}`,
      orderNo: order.orderNo,
      price: Number.isInteger(yuan) ? String(yuan) : yuan.toFixed(2),
      quantity: order.passengerCount || 1,
      ticketType: order.seatType ? t(`railway.list.seat.${order.seatType}`) : ''
    };
  } catch (error) {
    console.error('获取车票订单详情失败:', error);
    ElMessage.error(t('railway.orders.loadFailed'));
  }
};

// 加载会员开通订单详情
const loadMemberOrder = async (orderNo) => {
  try {
    const response = await getMyMemberOrders();
    const list = Array.isArray(response?.data) ? response.data : [];
    const order = list.find((row) => String(row.orderNo) === String(orderNo));
    if (!order) {
      ElMessage.error(t('payment.loadOrderFailed'));
      return;
    }
    memberOrder.value = order;
    item.value = {
      id: order.id,
      name: order.packageName,
      orderNo: order.orderNo,
      price: Number(order.amount || 0),
      quantity: 1,
      ticketType: t('payment.memberPackage')
    };
  } catch (error) {
    console.error('获取会员订单详情失败:', error);
    ElMessage.error(t('payment.loadOrderFailed'));
  }
};

// 归一化待支付订单ID（购物车/预订一次可能生成多笔订单）
const resolveOrderIds = () => {
  const fromProps = Array.isArray(props.orderIds) ? props.orderIds.filter(Boolean) : [];
  if (fromProps.length > 0) return fromProps.map(String);
  if (props.orderId) return [String(props.orderId)];
  if (route.query.orderId) return [String(route.query.orderId)];
  return [];
};

const orderTypeText = (itemType) => {
  const map = {
    food: t('payment.food'),
    product: t('payment.product'),
    hotel: t('payment.hotel'),
    ticket: t('payment.ticket'),
    points: t('payment.points')
  };
  return map[itemType] || t('payment.goods');
};

const mapBizType = (itemType) => {
  const type = String(itemType || '').toLowerCase();
  if (type === 'hotel') return 'HOTEL';
  if (type === 'ticket') return 'TICKET';
  if (type === 'points') return 'POINTS';
  if (type === 'group') return 'GROUP';
  return 'MALL';
};

// 加载商城/预订订单详情（支持多笔）
const loadMallOrders = async (ids) => {
  try {
    const results = await Promise.all(ids.map((id) => getOrderDetail(id).catch(() => null)));
    const list = results
      .filter((res) => res?.code === 200 && res.data)
      .map((res) => res.data);
    if (list.length === 0) {
      ElMessage.error(t('payment.loadOrderFailed'));
      return;
    }
    orderDetails.value = list;
    const totalAmount = Number(
      list.reduce((sum, order) => sum + Number(order.amount || 0), 0).toFixed(2)
    );
    const totalQuantity = list.reduce((sum, order) => sum + Number(order.quantity || 1), 0);
    const first = list[0];
    item.value = {
      id: ids.length === 1 ? first.itemId : undefined,
      name: ids.length === 1 ? first.itemName : t('payment.multiOrderName', { count: list.length }),
      orderNo: ids.length === 1 ? first.orderNo : list.map((order) => order.orderNo).join('、'),
      price: totalAmount,
      quantity: totalQuantity,
      ticketType: ids.length === 1 ? orderTypeText(first.itemType) : t('payment.mergedPayment')
    };
  } catch (error) {
    console.error('获取订单详情失败:', error);
    ElMessage.error(t('payment.loadOrderFailed'));
  }
};

// 从props或路由查询参数中获取商品信息和订单ID
onMounted(async () => {
  // 生成订单时间
  orderTime.value = generateOrderTime();
  
  // 优先使用props传递的参数，如果没有则使用路由参数
  const cartItemsParam = props.cartItems || route.query.cartItems;
  orderIds.value = resolveOrderIds();
  orderId.value = orderIds.value[0] || '';
  
  // 有订单ID时统一从订单详情构建支付目标（支持一次结算多笔订单）
  if (orderIds.value.length > 0) {
    if (props.orderType === 'railway') {
      await loadRailwayOrder();
    } else if (props.orderType === 'member') {
      await loadMemberOrder(orderIds.value[0]);
    } else {
      await loadMallOrders(orderIds.value);
    }
  } else if (cartItemsParam) {
    // 如果有购物车数据，使用购物车数据
    try {
      let parsedCartItems = cartItemsParam;
      
      // 如果是字符串，尝试解析为JSON
      if (typeof cartItemsParam === 'string') {
        const decodedCartItems = decodeURIComponent(cartItemsParam);
        parsedCartItems = JSON.parse(decodedCartItems);
      }
      
      console.log('购物车数据:', parsedCartItems); // 调试日志
      
      if (parsedCartItems && parsedCartItems.length > 0) {
        // 计算总价格
        const totalPrice = parsedCartItems.reduce((sum, cartItem) => sum + (cartItem.price * cartItem.quantity), 0);
        
        // 构建商品信息（如果是多个商品，显示汇总信息）
        if (parsedCartItems.length === 1) {
          const cartItem = parsedCartItems[0];
          item.value = {
            id: cartItem.id,
            name: cartItem.itemName || cartItem.name,
            price: totalPrice,
            quantity: cartItem.quantity,
            ticketType: cartItem.itemType === 'food' ? t('payment.food') : t('payment.product')
          };
        } else {
          item.value = {
            name: t('payment.multiItemName', { count: parsedCartItems.length }),
            price: totalPrice,
            quantity: parsedCartItems.reduce((sum, cartItem) => sum + cartItem.quantity, 0),
            ticketType: t('payment.mixedGoods')
          };
        }
      }
      // 清除可能的状态值，确保用户选择支付方式
      selectedPaymentMethod.value = '';
    } catch (error) {
      console.error('处理购物车数据失败:', error);
    }
  } else if (route.query.item) {
    // 如果没有订单ID，使用路由参数中的商品信息
    try {
      const decodedItem = decodeURIComponent(route.query.item);
      const parsedItem = JSON.parse(decodedItem);
      console.log('解析后item对象:', parsedItem); // 调试日志
      if (parsedItem.list && typeof parsedItem.list === 'object') {
        const ticketType = [
          t('payment.adultTicket'),
          t('payment.childTicket'),
          t('payment.familyTicket'),
          t('payment.vipTicket')
        ][parsedItem.selectedTicketIndex || 0];
        item.value = {
          ...parsedItem.list,
          price: parsedItem.price || parsedItem.list.price || 0,
          quantity: parsedItem.quantity || parsedItem.list.quantity || 1, // 重置quantity为默认值
          selectedTicketIndex: parsedItem.selectedTicketIndex || 0,
          ticketType: ticketType
        };
      } else {
        item.value = parsedItem;
      }
      // 清除可能的状态值，确保用户选择支付方式
      selectedPaymentMethod.value = '';
    } catch (error) {
      console.error('解析item参数失败:', error);
    }
  }
});

// 构建本次支付目标（每笔业务订单生成一条支付单）
const buildPaymentTargets = () => {
  if (props.orderType === 'railway') {
    const order = railwayOrder.value;
    if (!order?.orderNo) {
      throw new Error(t('payment.railwayOrderIncomplete'));
    }
    return [{
      bizOrderNo: order.orderNo,
      bizType: 'RAILWAY',
      totalAmount: Number(item.value.price || 0),
      subject: item.value.name || t('payment.railwaySubject', { orderNo: order.orderNo })
    }];
  }
  if (props.orderType === 'member') {
    const order = memberOrder.value;
    if (!order?.orderNo) {
      throw new Error(t('payment.memberOrderIncomplete'));
    }
    return [{
      bizOrderNo: order.orderNo,
      bizType: 'MEMBER',
      totalAmount: Number(order.amount || 0),
      subject: t('payment.memberSubject', { name: order.packageName })
    }];
  }
  if (orderDetails.value.length > 0) {
    return orderDetails.value.map((order) => ({
      bizOrderNo: order.orderNo,
      bizType: mapBizType(order.itemType),
      totalAmount: Number(order.amount || 0),
      subject: order.itemName
    }));
  }
  throw new Error(t('payment.orderIncomplete'));
};

// 真实渠道：并行轮询支付结果
const waitForPayments = async (payments) => {
  await Promise.all(payments.map((payment) => waitForPayment(payment.payNo)));
};

// 确认支付
const confirmPayment = async () => {
  // 检查是否有token
  const token = localStorage.getItem('token');
  if (!token) {
    ElMessage.error(t('payment.loginRequired'));
    router.push('/login');
    return;
  }

  if (!selectedPaymentMethod.value) {
    isAlertVisible.value = true;
    alertMessage.value = t('payment.methodRequired');
    return;
  }

  if (orderIds.value.length === 0) {
    isAlertVisible.value = true;
    alertMessage.value = t('payment.orderRequired');
    return;
  }

  let targets;
  try {
    targets = buildPaymentTargets();
  } catch (error) {
    isAlertVisible.value = true;
    alertMessage.value = error.message || t('payment.orderIncomplete');
    return;
  }
  if (targets.length === 0 || targets.some((target) => !(target.totalAmount > 0))) {
    isAlertVisible.value = true;
    alertMessage.value = t('payment.amountInvalid');
    return;
  }

  paying.value = true;
  try {
    // 统一走聚合支付网关：每笔业务订单创建一条支付单
    const created = [];
    for (const target of targets) {
      const response = await createPayment({
        ...target,
        channelCode: selectedPaymentMethod.value,
        expireMinutes: 30
      });
      if (response?.code !== 200 || !response.data) {
        throw new Error(response?.message || t('payment.createFailed'));
      }
      created.push(response.data);
    }

    const pending = created.filter((payment) => payment.status !== 'SUCCESS');
    const mockPending = pending.filter((payment) => payment.payParams?.mock);
    const channelPending = pending.filter((payment) => !payment.payParams?.mock);

    if (mockPending.length > 0) {
      // 模拟渠道：静默确认支付，不再弹出二次确认框
      await confirmMockPayments(mockPending);
    }

    if (channelPending.length > 0) {
      await waitForPayments(channelPending);
    }

    isPaymentModalVisible.value = true;
  } catch (error) {
    console.error('支付请求失败:', error);
    isAlertVisible.value = true;
    alertMessage.value = error?.message || t('payment.payFailed');
  } finally {
    paying.value = false;
  }
};

// 模拟渠道：逐笔确认支付并校验支付结果
const confirmMockPayments = async (payments) => {
  for (const payment of payments) {
    const confirmed = await mockConfirmPayment(payment.flowNo);
    if (confirmed?.code !== 200) {
      throw new Error(confirmed?.message || t('payment.payFailed'));
    }
    const queried = await queryPayment(payment.payNo);
    if (queried?.code !== 200 || queried.data?.status !== 'SUCCESS') {
      throw new Error(queried?.message || t('payment.payIncomplete'));
    }
  }
};

// 关闭自定义提示框
const closeAlert = () => {
  isAlertVisible.value = false;
};

// 点击支付弹窗遮罩（卡片以外的空白区域）关闭弹窗
// 与支付成功的 closeModal 消息区分，避免被父组件误判为支付成功
const handleContainerClick = () => {
  if (paying.value) return;
  window.parent.postMessage({ action: 'closePay' }, '*');
};

// 关闭支付成功模态框
const closeModal = () => {
  isPaymentModalVisible.value = false;
  // 支付成功后自动关闭页面
  setTimeout(() => {
    window.parent.postMessage({ action: 'closeModal' }, '*');
  }, 1000);
};
</script>

